mapper.insert:
MERGE INTO iot_shared_value_dict_v3 t USING (
SELECT #{item.id} AS `id`, #{item.dictType} AS `dict_type`, #{item.dictValue} AS `dict_value`, #{item.dictLabel} AS `dict_label`, 1 AS `use_count`, #{item.sortOrder} AS `sort_order`, #{item.status} AS `status`, #{item.remark} AS `remark`, #{item.tenant} AS `tenant`, #{item.createBy} AS `create_by`, NOW() AS `create_time`, 0 AS `deleted` FROM DUAL
) s ON (t.`tenant` = s.`tenant` AND t.`dict_type` = s.`dict_type` AND t.`dict_value` = s.`dict_value` AND t.`deleted` = s.`deleted`) WHEN MATCHED THEN UPDATE SET t.`use_count` = t.`use_count` + 1, t.`update_time` = NOW() WHEN NOT MATCHED THEN INSERT (`id`, `dict_type`, `dict_value`, `dict_label`, `use_count`, `sort_order`, `status`, `remark`, `tenant`, `create_by`, `create_time`) VALUES (s.`id`, s.`dict_type`, s.`dict_value`, s.`dict_label`, s.`use_count`, s.`sort_order`, s.`status`, s.`remark`, s.`tenant`, s.`create_by`, s.`create_time`)

mapper.select:
SELECT `dict_value`
FROM iot_shared_value_dict_v3
WHERE `dict_type` = #{dictType}
  AND `status` = 1

    AND (
        `dict_value` LIKE CONCAT('%', #{keyword}, '%')
        OR `dict_label` LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY `use_count` DESC, `sort_order` ASC

    LIMIT #{limit}
